import * as bookingService from "./booking.service.js";
// ============================================================
// CREATE BOOKING
//
// IMPORTANT:
// This is the ONLY place where Booking is created.
//
// Confirm Button
// POST /api/bookings
//
// bookingId is generated by the backend here.
// ============================================================
export const createBooking = async (req, res) => {
    try {
        if (!req.user?.id) {
            return res.status(401).json({
                success: false,
                message: "Authentication required.",
            });
        }
        const booking = await bookingService.createBooking({
            ...req.body,
            passengerId: Number(req.user.id),
        });
        return res.status(201).json({
            success: true,
            data: booking,
        });
    }
    catch (error) {
        console.error("CREATE BOOKING ERROR:", error);
        return res.status(500).json({
            success: false,
            message: error?.message ||
                "Unable to create booking.",
        });
    }
};
// ============================================================
// GET BOOKING
// ============================================================
export const getBooking = async (req, res) => {
    try {
        const id = Number(req.params.id);
        if (!Number.isInteger(id)) {
            return res.status(400).json({
                success: false,
                message: "Invalid booking ID.",
            });
        }
        const booking = await bookingService.getBooking(id);
        if (!booking) {
            return res.status(404).json({
                success: false,
                message: "Booking not found.",
            });
        }
        return res.status(200).json({
            success: true,
            data: booking,
        });
    }
    catch (error) {
        console.error("GET BOOKING ERROR:", error);
        return res.status(500).json({
            success: false,
            message: error?.message ||
                "Unable to get booking.",
        });
    }
};
// ============================================================
// RESERVE DRIVER
//
// IMPORTANT:
// NO bookingId.
//
// Driver card click:
// POST /api/bookings/reservations
//
// Body:
// {
//   driverProfileId: 123
// }
//
// Passenger comes from auth token.
//
// Reservation is temporary only.
// ============================================================
export const reserveDriver = async (req, res) => {
    try {
        if (!req.user?.id) {
            return res.status(401).json({
                success: false,
                message: "Authentication required.",
            });
        }
        const driverProfileId = Number(req.body?.driverProfileId);
        if (!Number.isInteger(driverProfileId)) {
            return res.status(400).json({
                success: false,
                message: "Valid driver profile ID is required.",
            });
        }
        const passengerId = Number(req.user.id);
        const reservation = await bookingService.reserveDriver(driverProfileId, passengerId);
        return res.status(200).json({
            success: true,
            data: reservation,
        });
    }
    catch (error) {
        console.error("RESERVE DRIVER ERROR:", error);
        return res.status(409).json({
            success: false,
            message: error?.message ||
                "Unable to reserve driver.",
        });
    }
};
